71	  async createLocation(input: LocationInput): Promise<Location> {
72	    const location = await this.db.transaction(async tx => {
73	      // Attempt to find a previous location matching the input
74	      const previousLocations = await this.locations(tx);
75	      // TODO: when location id's are a compilation of input target we can remove this full
76	      // lookup of locations first and just grab the by that instead.
77	      const previousLocation = previousLocations.some(
78	        l => input.type === l.type && input.target === l.target,
79	      );
80	      if (previousLocation) {
