    const exactLocationsToDelete = new Set<string>();
    const locationPrefixesToDelete = new Set<string>();
    // Since Location entities are named after their target URL, moves
    // unfortunately have to be translated into deletion and creation. We keep
    // them separate from plain deletions/creations so that the action taken can
    // be reported as a "move" for metrics purposes.
    const exactLocationsToMoveFrom = new Set<string>();
    const exactLocationsToMoveTo = new Set<string>();
    const locationPrefixesToMove = new Map<string, string>();

    for (const event of events) {
      if (
        event.type === 'location.deleted' &&
        this.scmEventHandlingConfig.unregister
      ) {
        exactLocationsToDelete.add(event.url);
      } else if (
        event.type === 'location.moved' &&
        this.scmEventHandlingConfig.move
      ) {
        exactLocationsToMoveFrom.add(event.fromUrl);
        exactLocationsToMoveTo.add(event.toUrl);
      } else if (
        event.type === 'repository.deleted' &&
        this.scmEventHandlingConfig.unregister
      ) {
        locationPrefixesToDelete.add(event.url);
      } else if (
        event.type === 'repository.moved' &&
        this.scmEventHandlingConfig.move
      ) {
        // These also have to be handled with deletions and creations
        locationPrefixesToMove.set(event.fromUrl, event.toUrl);
      }
    }

    // location.deleted: locations are removed, and potentially a new location
    // is created if the underlying URL changed.
    if (exactLocationsToDelete.size > 0) {
      const deleted = await this.#deleteLocationsByExactUrl(
        exactLocationsToDelete,
      );
      if (deleted > 0) {
        this.scmEvents.markEventActionTaken({ count: 1, action: 'delete' });
      }
      const created = await this.#createLocationsByExactUrl(
        exactLocationsToDelete,
      );
      if (created > 0) {
        this.scmEvents.markEventActionTaken({ count: 1, action: 'create' });
      }
    }

    // repository.deleted: matching locations are removed.
    if (locationPrefixesToDelete.size > 0) {
      const deleted = await this.#deleteLocationsByUrlPrefix(
        locationPrefixesToDelete,
      );
      if (deleted > 0) {
        this.scmEvents.markEventActionTaken({ count: 1, action: 'delete' });
      }
    }

    // location.moved: the old location is deleted and a new one created, which
    // is reported as a single move action.
    if (exactLocationsToMoveFrom.size > 0 || exactLocationsToMoveTo.size > 0) {
      let moved = 0;
      if (exactLocationsToMoveFrom.size > 0) {
        moved += await this.#deleteLocationsByExactUrl(exactLocationsToMoveFrom);
      }
      if (exactLocationsToMoveTo.size > 0) {
        moved += await this.#createLocationsByExactUrl(exactLocationsToMoveTo);
      }
      if (moved > 0) {
        this.scmEvents.markEventActionTaken({ count: 1, action: 'move' });
      }
    }

    // repository.moved: matching locations are moved to their new prefix.
    if (locationPrefixesToMove.size > 0) {
      const moved = await this.#moveLocationsByUrlPrefix(locationPrefixesToMove);
      if (moved > 0) {
        this.scmEvents.markEventActionTaken({ count: 1, action: 'delete' });
      }
    }
